def max_permutation_value(N):
    if N % 2 == 0:
        return (N * (N + 1)) // 2
    else:
        return ((N - 1) * (N + 1)) // 2

def main():
    T = int(input())
    results = []
    for _ in range(T):
        N = int(input())
        results.append(max_permutation_value(N))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
